const r = await tools.mcp__executor_personal__execute({code: `
const queries = ["projects get project", "projects list projects", "environment variables list", "deployments list", "integrations resources list", "storage list"];
const out = [];
for (const query of queries) {
  const search = await tools.search({ namespace: "vercel_api", query, limit: 20 });
  out.push({ query, items: search.items.map((x) => ({ path: x.path, description: x.description })) });
}
return out;
`});
text(r);

