  cmd: "rg -n 'BUNDJIL_|UPSTASH_|KV_REST' apps/codex-proxy packages/codex-oauth docs/product-specs/codex-hosted-live-oauth-storage.md | head -220 && jq '{projectId_present:(.projectId|type==\"string\"),orgId_present:(.orgId|type==\"string\")}' apps/codex-proxy/.vercel/project.json && command -v vercel || true && vercel --version 2>/dev/null || true",
