const projectName = "bundjil-codex-proxy";
const desired = [
  { key: "BUNDJIL_CODEX_PROFILE_ID", value: "default", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_CONNECTOR_ID", value: "bundjil-local", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_INSTALLATION_ID", value: "agent-dev", type: "plain", target: ["preview"] },
  { key: "BUNDJIL_CODEX_SUBJECT_ID", value: "personal-owner", type: "plain", target: ["preview"] }
];

const write = await tools.vercel_api.user.personalvercelapi.projects.createProjectEnv({
  idOrName: projectName,
  upsert: "true",
  body: desired
});
if (!write.ok) {
  return { ok: false, stage: "upsert", code: write.error.code };
}

const metadata = await tools.vercel_api.user.personalvercelapi.projects.filterProjectEnvs({
  idOrName: projectName,
  decrypt: "false"
});
if (!metadata.ok) {
  return { ok: false, stage: "metadata-readback", code: metadata.error.code };
}

const rawEnvs = Array.isArray(metadata.data)
  ? metadata.data
  : ("envs" in metadata.data ? metadata.data.envs : [metadata.data]);
